<script setup lang="ts">import{onMounted,ref}from'vue';import{ElMessage}from'element-plus';import{http,type ApiResponse}from'../api/http';interface Role{id:number;roleName:string;roleCode:string};interface P{id:number;permissionName:string;permissionCode:string;permissionType:string};interface D{id:number;departmentName:string;enabled:boolean};const roles=ref<Role[]>([]),permissions=ref<P[]>([]),departments=ref<D[]>([]),roleId=ref<number>(),selected=ref<number[]>([]),deptSelected=ref<number[]>([]);const load=async()=>{roles.value=(await http.get<ApiResponse<Role[]>>('/system/roles')).data.data;permissions.value=(await http.get<ApiResponse<P[]>>('/system/permissions')).data.data;departments.value=(await http.get<ApiResponse<D[]>>('/system/departments')).data.data};const choose=async(id:number)=>{roleId.value=id;selected.value=(await http.get<ApiResponse<number[]>>('/system/permissions/roles/'+id)).data.data;deptSelected.value=(await http.get<ApiResponse<number[]>>('/system/permissions/roles/'+id+'/departments')).data.data};const save=async()=>{if(!roleId.value)return;await http.put('/system/permissions/roles/'+roleId.value,{permissionIds:selected.value});await http.put('/system/permissions/roles/'+roleId.value+'/departments',{departmentIds:deptSelected.value});ElMessage.success('权限范围已保存')};onMounted(load)</script>
<template><section class="page-card"><h2>权限管理</h2><div class="filter-bar"><el-select v-model="roleId" placeholder="选择角色" @change="choose"><el-option v-for="r in roles" :key="r.id" :label="r.roleName" :value="r.id"/></el-select><el-button v-permission="'PERM_API_ROLE_MANAGE'" type="primary" @click="save">保存权限</el-button></div><el-divider/><el-form label-position="top"><el-form-item label="菜单权限"><el-checkbox-group v-model="selected"><el-checkbox v-for="p in permissions.filter(x=>x.permissionType==='MENU')" :key="p.id" :value="p.id">{{p.permissionName}}</el-checkbox></el-checkbox-group></el-form-item><el-form-item label="接口及字段权限"><el-checkbox-group v-model="selected"><el-checkbox v-for="p in permissions.filter(x=>x.permissionType!=='MENU')" :key="p.id" :value="p.id">{{p.permissionName}}</el-checkbox></el-checkbox-group></el-form-item><el-form-item label="可访问科室"><el-checkbox-group v-model="deptSelected"><el-checkbox v-for="d in departments.filter(x=>x.enabled)" :key="d.id" :value="d.id">{{d.departmentName}}</el-checkbox></el-checkbox-group></el-form-item></el-form></section></template>
